        $config = @{
            os        = @('ubuntu-latest')
            fail_fast = $false
        }

        $result = New-EnvironmentMatrix -Config $config

        $result.'fail-fast' | Should -Be $false
    }

    It 'defaults fail-fast to true when not specified' {
        $config = @{ os = @('ubuntu-latest') }

        $result = New-EnvironmentMatrix -Config $config

        $result.'fail-fast' | Should -Be $true
